{"path": "forth.py", "content": "class StackUnderflowError(Exception):
    """Raised when the stack does not hold enough items."""

    def __init__(self, message="Insufficient number of items in stack"):
        super().__init__(message)
        self.message = message


def _is_number(token):
    return token.isascii() and token.isdigit()


def _pop2(stack):
    if len(stack) < 2:
        raise StackUnderflowError("Insufficient number of items in stack")
    b = stack.pop()
    a = stack.pop()
    return a, b


def _add(s):
    a, b = _pop2(s)
    s.append(a + b)


def _sub(s):
    a, b = _pop2(s)
    s.append(a - b)


def _mul(s):
    a, b = _pop2(s)
    s.append(a * b)


def _div(s):
    if len(s) < 2:
        raise StackUnderflowError("Insufficient number of items in stack")
    if s[-1] == 0:
        raise ZeroDivisionError("divide by zero")
    a, b = _pop2(s)
    s.append(int(a / b) if abs(a) < 2**52 else (abs(a) // abs(b)) * (1 if (a < 0) == (b < 0) else -1))


def _dup(s):
    if not s:
        raise StackUnderflowError("Insufficient number of items in stack")
    s.append(s[-1])


def _drop(s):
    if not s:
        raise StackUnderflowError("Insufficient number of items in stack")
    s.pop()


def _swap(s):
    a, b = _pop2(s)
    s.extend((b, a))


def _over(s):
    a, b = _pop2(s)
    s.extend((a, b, a))


BUILTINS = {
    "+": _add, "-": _sub, "*": _mul, "/": _div,
    "dup": _dup, "drop": _drop, "swap": _swap, "over": _over,
}


def evaluate(input_data):
    stack = []
    custom = {}  # name -> list of primitive tokens (already expanded)
    for line in input_data:
        tokens = line.lower().split()
        i = 0
        while i < len(tokens):
            tok = tokens[i]
            if tok == ":":
                try:
                    end = tokens.index(";", i)
                except ValueError:
                    raise ValueError("unterminated definition") from None
                body = tokens[i + 1:end]
                if not body:
                    raise ValueError("illegal operation")
                name, definition = body[0], body[1:]
                if _is_number(name):
                    raise ValueError("illegal operation")
                expanded = []
                for t in definition:
                    expanded.extend(custom.get(t, [t]))
                custom[name] = expanded
                i = end + 1
                continue
            for t in custom.get(tok, [tok]):
                if _is_number(t):
                    stack.append(int(t))
                elif t in BUILTINS:
                    BUILTINS[t](stack)
                else:
                    raise ValueError("undefined operation")
            i += 1
    return stack
